-- 065_agent_cjournal_scholars.sql — V395-24: 政经 C 刊选题学者库
-- 学者方法论动态化（三学者内置 + 用户可添加新学者）
CREATE TABLE IF NOT EXISTS cjournal_scholars (
  id text PRIMARY KEY,                       -- 方法 id（如 renbaoping / 用户自定义）
  scholar text NOT NULL,                     -- 学者名（如 任保平（西北大学））
  concept text NOT NULL,                     -- 方法概念一句话（如 热点要机制化）
  method text NOT NULL,                      -- 方法框架（如 新经济现象→生产力理论→机制建构）
  detail text NOT NULL DEFAULT '',           -- 方法详解（文章原文级, 注入 LLM prompt）
  builtin boolean NOT NULL DEFAULT false,    -- 内置（不可删除）
  created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO cjournal_scholars (id, scholar, concept, method, detail, builtin) VALUES
  ('renbaoping', '任保平（西北大学）', '热点要机制化', '新经济现象 → 生产力理论 → 机制建构（技术-要素-组织-生态四层框架）', '任保平教授的核心方法是「新经济现象 → 生产力理论 → 机制建构」。三个转换：①把政策热词转换成理论问题（不是「新质生产力高质量发展研究」，而是「新质生产力究竟意味着生产力发生了什么质态变化？」）②把一个热点放进经典范畴（新质生产力→生产力理论、数字经济→生产方式、数据要素→生产要素理论、人工智能→劳动过程）③再构造一个自己的解释框架（如「技术—要素—组织—生态」四层框架、「决定层—基础层—承载层」），产生论文的理论辨识度。', true),
  ('zhouwen', '周文（复旦大学）', '政策概念要学理化', '中国实践 → 标识性概念 → 自主知识体系（实践→经验→概念→理论→体系）', '周文教授的核心方法是「中国实践 → 标识性概念 → 自主知识体系」。三个要点：①不是找「新词」，而是找「标识性概念」（中国式现代化、高质量发展、新质生产力、共同富裕、有效市场与有为政府、人文经济学——具有形成自主理论体系潜力的概念）②从「中国现象」中寻找理论问题（中国社会主义市场经济为什么既需要充分发挥市场作用，又需要国家战略协调？）③努力形成自己的概念链：中国实践 → 标识性概念 → 理论命题 → 范畴体系 → 自主知识体系。强调经过「实践 → 经验 → 概念 → 理论 → 体系」的学理化过程。', true),
  ('zhoushaodong', '周绍东（武汉大学）', '现实问题要经典化', '经典范畴 → 现实问题 → 理论再解释（数字平台+地租理论、AI劳动+劳动过程理论）', '周绍东教授的核心方法是「经典范畴 → 现实问题 → 理论再解释」。核心是「旧理论不等于旧选题」：马克思的地租理论、再生产理论、分工理论、利润率理论、劳动过程理论、社会经济形态理论，完全可以解释非常新的问题（平台经济、数字劳动、人工智能、人口变化、空间经济、新质生产力）。真正重要的是找到「经典理论与现实问题之间新的张力」。典型选题方式：现实新现象 + 一个非常具体的马克思主义经典理论（数字平台+地租理论、人工智能劳动+劳动过程理论、人口高质量发展+社会再生产理论、全国统一大市场+社会总资本再生产理论）。', true)
ON CONFLICT (id) DO NOTHING;
